def parcala(iterable, boyut):
    if boyut < 1:
        raise ValueError("boyut en az 1 olmalı")
    parca = []
    for x in iterable:
        parca.append(x)
        if len(parca) == boyut:
            yield parca
            parca = []
    if parca:
        yield parca
